const DiagramLayout=(()=>{
function fitScale(graph,box){if(!(graph.width>0&&graph.height>0&&box.width>0&&box.height>0))throw Error('Geometry must be positive');return Math.min(1,Math.max(1,box.width-32)/graph.width,Math.max(1,box.height-100)/graph.height);}
function wrapLabel(text,limit=44){const rows=[''];for(const word of text.split(' ')){const i=rows.length-1;if(rows[i]&&rows[i].length+word.length+1>limit)rows.push(word);else rows[i]+=(rows[i]?' ':'')+word;}return rows.join('<br/>');}
return {fitScale,wrapLabel};})();if(typeof module!=='undefined')module.exports=DiagramLayout;

const SpecialistModel=(()=>{
function specialists(catalog){
 if(!catalog||!Array.isArray(catalog.modules)||catalog.modules.length!==8)throw Error('Exactly eight specialist modules required');
 const rows=catalog.modules.map((m,i)=>({id:'specialist_'+String(i+1).padStart(2,'0'),module:m.id,name:m.name,scope:m.scope,topics:JSON.parse(JSON.stringify(m.items))}));
 if(rows.reduce((n,m)=>n+m.topics.length,0)!==50)throw Error('Expected 50 source topics');
 return rows;
}
function expand(view,catalog,enabled){
 const v=JSON.parse(JSON.stringify(view));if(!enabled||v.id!=='rubrics')return v;
 const rows=specialists(catalog),ids=v.groups.flatMap(g=>g[2]);
 if(!ids.includes('specialists'))throw Error('Team node missing');
 for(const group of v.groups){const i=group[2].indexOf('specialists');if(i>=0)group[2].splice(i+1,0,...rows.map(m=>m.id));}
 v.edges=v.edges.filter(e=>!(e[0]==='specialists'&&e[1]==='integrator'));
 for(const m of rows){v.edges.push(['specialists',m.id,m.topics.length+' assigned topics']);v.edges.push([m.id,'integrator','case-specific proposals']);}
 return v;
}
return {specialists,expand};})();
if(typeof module!=='undefined')module.exports=SpecialistModel;

const specialistCatalog={"version":"integrated-checklist-catalog.v1","origin_version":"osce-checklist-design.r2.errata1.host-schema-guard","origin_sha256":"05884fdfb9e82c433942d359f7ca50124a5276b4140b85c10bfc58465a986c2a","status":"development_unreviewed","scope":"Generic element types only; private workbook examples and unresolved clinical questions remain in original evidence. Stage adaptation is new integration behavior.","modules":[{"id":"MOD-01","name":"History & Context Elicitation","scope":"Clinician inquiry into presenting symptoms, competing differentials, organ/systemic red flags, medication/allergy/preventive/ophthalmic history, longitudinal data discrepancies, exposures, functional/access/self-management context, and collateral history.","items":[{"id":"M1-I1","question":"Does the clinician characterize the primary symptom pattern and probe competing syndromic differentials beyond the volunteered complaint?","include_when":"The presentation involves undifferentiated, overlapping, or self-framed symptoms where anchoring on the opening complaint risks missing a primary or coexisting etiology.","exclude_when":"The diagnosis is already established and the encounter focuses solely on stable follow-up or a targeted procedural transition without new symptoms.","adequate":"Clinician systematically asks about symptom onset, quality, pattern, and differentiating features across plausible syndromic alternatives.","insufficient":"Clinician accepts the patient's initial framing without probing differentiating symptom clusters.","basis":"unresolved_source_support"},{"id":"M1-I2","question":"Does the clinician actively screen for acute, systemic, or organ-specific red-flag symptoms during history-taking?","include_when":"The presenting complaint or clinical trajectory carries a plausible risk of life-, organ-, vision-, or psychiatric safety-threatening complications.","exclude_when":"No plausible red-flag syndrome applies to the presenting problem or visit stage.","adequate":"Clinician explicitly inquires about relevant warning symptoms for the affected system (including self-harm or safety risk where indicated) during assessment.","insufficient":"Clinician omits red-flag inquiry and relies on the patient to volunteer alarm symptoms unprompted.","basis":"unresolved_source_support"},{"id":"M1-I3","question":"Does the clinician elicit or re-verify relevant prescription drugs, over-the-counter products, supplements, allergies, and pertinent preventive or ophthalmic history?","include_when":"Diagnostic evaluation, safe prescribing, or preventive care depends on current medications, self-medication, administration habits, allergies, immunization/screening status, or baseline eye/vision history.","exclude_when":"Medication, allergy, and relevant preventive/ophthalmic histories are already verified for the current decision and unchanged.","adequate":"Clinician proactively asks about relevant prescribed and non-prescribed agents, allergies, and pertinent preventive or ophthalmic history before making dependent clinical decisions, accepting unknown answers if unscripted.","insufficient":"Clinician prescribes or interprets findings without checking relevant concurrent agents, allergies, or required baseline preventive/ophthalmic history.","basis":"design_extension"},{"id":"M1-I4","question":"Does the clinician nonjudgmentally probe and reconcile discrepancies between objective findings and reported history or adherence?","include_when":"Returned test results, vital signs, or symptom trajectory conflict with the patient's prior statements, self-reported diagnosis, or expected treatment response.","exclude_when":"History, reported adherence, and objective findings are concordant across visits.","adequate":"Clinician identifies the contradiction and asks targeted questions about interval habits, pre-test actions, or prior records to clarify the clinical picture (scored on the clinician's inquiry, regardless of patient disclosure).","insufficient":"Clinician ignores the discrepancy, orders invasive workup for an unverified claim, or labels treatment a failure without inquiring about confounders.","basis":"unresolved_source_support"},{"id":"M1-I5","question":"Does the clinician inquire about relevant occupational hazards, environmental triggers, travel/infectious exposures, substance use, or family history?","include_when":"Etiology, risk stratification, or management depends on workplace irritants/ergonomics, household allergens, travel or dietary exposures, tobacco/alcohol/substance use, or hereditary disease patterns.","exclude_when":"Occupational, environmental, infectious, substance, and familial factors have no bearing on the clinical problem.","adequate":"Clinician asks targeted questions regarding the applicable exposure, substance quantification, or family history domain.","insufficient":"Clinician focuses narrowly on symptoms and omits exposure, substance, or familial risk inquiry supported by the case.","basis":"workbook_exemplar"},{"id":"M1-I6","question":"Does the clinician proactively inquire about functional/daily-living impact, healthcare access or self-management barriers, social support, and collateral history (with appropriate consent)?","include_when":"Symptoms or proposed care may affect work, daily function, or independent living; logistics/access or self-management capacity may constrain care; or a witness/caregiver is involved or insight is impaired.","exclude_when":"The encounter is a straightforward solo visit where functional impact, access, support, and collateral history are already clear and uninvolved.","adequate":"Clinician proactively asks how symptoms affect daily function/work, checks practical access/self-management capability and support (accepting unknown answers when unscripted), and in triadic visits integrates collateral history while respecting patient engagement and confidentiality/consent.","insufficient":"Clinician omits functional, access, or support inquiry when relevant, accepts anosognosic minimization without exploring collateral context, or shares/solicits third-party information without addressing consent.","basis":"design_extension"}]},{"id":"MOD-02","name":"Examination & Diagnostic Stewardship","scope":"Targeted physical examination and vital signs, actionable exam deferral or modality coordination, clinical probability/severity scoring, confirmatory and exclusion test ordering, pre-analytical patient preparation instructions, pre-treatment safety labs, and diagnostic stewardship.","items":[{"id":"M2-I1","question":"Does the clinician perform or arrange required targeted physical examinations and vital sign assessments, or execute an actionable exam deferral?","include_when":"Clinical assessment requires specific bedside measurements, focused organ examination, virtual-to-in-person exam coordination, or context-sensitive deferral of an intimate or contraindicated maneuver.","exclude_when":"No physical examination maneuver or modality transition is clinically relevant at the visit.","adequate":"Clinician performs or requests the specific examination parameters, or when deferral/modality change is needed, explains why and arranges a concrete, actionable plan to complete the assessment safely.","insufficient":"Clinician omits essential physical findings, performs a contraindicated maneuver, or defers an exam without arranging an actionable follow-through plan.","basis":"workbook_exemplar"},{"id":"M2-I2","question":"Does the clinician assess parameters for and apply a relevant clinical probability, severity, or symptom-burden tool?","include_when":"Case context supports structured risk stratification to guide disposition, diagnostic testing, or treatment intensity.","exclude_when":"No structured clinical scoring or risk-stratification framework applies to the decision point.","adequate":"Clinician evaluates the constituent clinical parameters and applies the structured risk or severity assessment to inform management.","insufficient":"Clinician makes disposition or testing decisions without assessing severity parameters or risk probability.","basis":"workbook_exemplar"},{"id":"M2-I3","question":"Does the clinician order appropriate confirmatory, secondary-cause exclusion, or staged diagnostic investigations?","include_when":"Establishing the diagnosis, ruling out reversible mimics, or resolving equivocal baseline findings requires laboratory, microbiological, physiological, or imaging orders.","exclude_when":"Diagnostic evaluation is already complete and no further diagnostic or staging investigations are indicated.","adequate":"Clinician orders the case-supported confirmatory and exclusion investigations at the appropriate diagnostic stage.","insufficient":"Clinician initiates long-term disease-directed treatment without required diagnostic confirmation, omits secondary-cause exclusion testing, or fails to escalate staged testing when baseline results are inconclusive.","basis":"unresolved_source_support"},{"id":"M2-I4","question":"Does the clinician provide necessary pre-analytical patient preparation or specimen sequencing instructions when ordering tests?","include_when":"Test validity depends on patient preparation prior to sampling (such as medication holds, dietary continuation/fasting, or collecting cultures before starting antimicrobials).","exclude_when":"Ordered investigations require no special patient preparation or sequencing.","adequate":"Clinician clearly instructs the patient on required dietary, medication, or timing preparation before specimen collection or testing.","insufficient":"Clinician orders a preparation-sensitive investigation without instructing the patient on pre-test requirements.","basis":"unresolved_source_support"},{"id":"M2-I5","question":"Does the clinician practice diagnostic stewardship by withholding unindicated or duplicate tests and providing an actionable deferral explanation?","include_when":"A test is requested by the patient or commonly overused but is not clinically indicated at the current stage, or recent valid results already exist.","exclude_when":"All discussed or requested investigations are clinically indicated at the current visit.","adequate":"Clinician refrains from ordering the unnecessary or duplicate test, explains why it is not currently helpful, and outlines actionable clinical contingencies that would prompt future testing.","insufficient":"Clinician orders unindicated testing defensively or refuses a requested test abruptly without explaining the rationale and reassessment criteria.","basis":"unresolved_source_support"},{"id":"M2-I6","question":"Does the clinician order required baseline organ-function or safety-clearance investigations before starting high-risk therapy?","include_when":"Planned pharmacotherapy or biological treatment requires pre-treatment organ function, metabolic, hematologic, infectious, or cardiac clearance.","exclude_when":"The selected therapy requires no specific pre-treatment baseline laboratory or clearance testing.","adequate":"Clinician orders the necessary baseline safety or clearance investigations prior to or concurrently with treatment initiation.","insufficient":"Clinician starts high-risk pharmacotherapy without checking required baseline safety parameters.","basis":"unresolved_source_support"}]},{"id":"MOD-03","name":"Diagnostic & Prognostic Communication","scope":"Independently explaining the purpose of ordered investigations; interpreting returned lab, imaging, pathology, and discharge results; clarifying symptom attribution and misconceptions; communicating diagnostic uncertainty; disclosing serious news and realistic trajectories; and explaining hereditary risk.","items":[{"id":"M3-I1","question":"Does the clinician independently explain the clinical purpose of ordered investigations and what the patient should expect, regardless of whether the patient asks?","include_when":"The clinician orders diagnostic, staging, or baseline safety investigations during the encounter.","exclude_when":"No investigations are ordered at the visit.","adequate":"Clinician proactively explains in plain language why each test or panel is being ordered, what question it answers, and what the procedure involves, without waiting for the patient to prompt.","insufficient":"Clinician merely names or orders tests without explaining their diagnostic or safety purpose to the patient.","basis":"design_extension"},{"id":"M3-I2","question":"Does the clinician interpret and explain returned laboratory, imaging, pathology, or hospital discharge findings in plain language?","include_when":"New investigation reports or emergency/inpatient discharge summaries are available for review at the visit.","exclude_when":"No new diagnostic results or discharge summaries are present at the visit.","adequate":"Clinician walks through relevant abnormal and reassuringly normal findings and explains how they establish the diagnosis, disease stage, or clinical stability.","insufficient":"Clinician states only a diagnostic label without explaining the underlying test or discharge findings, or merely promises to review them later.","basis":"unresolved_source_support"},{"id":"M3-I3","question":"Does the clinician clarify symptom attribution, correct causal misconceptions, and provide evidence-based reassurance where serious pathology is excluded?","include_when":"The patient misattributes symptoms to an unrelated condition or medication, or expresses fear of malignancy, organ failure, or permanent harm.","exclude_when":"Symptom attribution is straightforward and no misconception or illness fear is present.","adequate":"Clinician directly addresses the patient's attribution belief or fear, explains the actual physiological cause of the symptoms, and reassures based on objective findings.","insufficient":"Clinician ignores the patient's causal misconception or fear, leaving anxiety or false attribution unaddressed.","basis":"unresolved_source_support"},{"id":"M3-I4","question":"Does the clinician communicate diagnostic uncertainty and explain the rationale for a provisional diagnosis or staged exclusion pathway?","include_when":"Initial findings are equivocal, normal between episodes, or discordant with clinical suspicion, requiring longitudinal observation or staged testing.","exclude_when":"Available findings establish a definitive, unambiguous diagnosis.","adequate":"Clinician explains why current results do not yet provide final certainty and outlines the logical next diagnostic or monitoring step without premature labeling.","insufficient":"Clinician asserts an unsupported definitive diagnosis on equivocal data or falsely rules out an episodic condition based on a normal baseline test.","basis":"unresolved_source_support"},{"id":"M3-I5","question":"Does the clinician disclose serious or chronic diagnoses empathetically and set realistic expectations for disease trajectory, control versus cure, or recovery timelines?","include_when":"The patient receives a serious, progressive, or chronic diagnosis, or asks about curability, long-term prognosis, or exact recovery dates.","exclude_when":"The condition is minor and self-limiting and the patient holds realistic recovery expectations.","adequate":"Clinician delivers diagnostic and prognostic information sensitively, clarifies ongoing disease control versus cure, and frames expected recovery or progression timelines honestly without false guarantees.","insufficient":"Clinician delivers serious news bluntly, promises an unrealistic cure or fixed recovery date, or evades direct prognostic questions.","basis":"workbook_exemplar"},{"id":"M3-I6","question":"Does the clinician counsel the patient on hereditary transmission risk, family screening implications, or the role of genetic counseling?","include_when":"The condition has a recognized familial or genetic component, or the patient asks about inheritance risk for relatives.","exclude_when":"No hereditary condition or patient question regarding familial risk is present.","adequate":"Clinician accurately explains the relevant inheritance pattern or low familial risk and discusses the value of family notification or genetic counseling (while test ordering and referral execution are handled by MOD-02 and MOD-08).","insufficient":"Clinician ignores family-risk questions or provides inaccurate heritability reassurance.","basis":"unresolved_source_support"}]},{"id":"MOD-04","name":"Pharmacotherapy & Safety Management","scope":"Initiating or continuing indicated therapy; resolving allergy, comorbidity, drug-interaction, and organ-function contraindications; stopping exacerbating agents; mitigating reproductive/teratogenic risk; stewarding antimicrobials and safe OTC use; and executing sequencing, titration, step-down, or adverse reaction adjustments.","items":[{"id":"M4-I1","question":"Does the clinician initiate or continue indicated condition-directed or supportive pharmacotherapy?","include_when":"Clinical findings or confirmed diagnoses warrant starting first-line disease-directed or symptomatic treatment, or maintaining an effective established regimen.","exclude_when":"Management is exclusively non-pharmacological, or pharmacotherapy must be deferred pending diagnostic confirmation or emergency transfer.","adequate":"Clinician prescribes or continues an appropriate, case-supported therapeutic class for the condition (with clinically sound alternatives accepted).","insufficient":"Clinician omits indicated first-line treatment or prematurely discontinues necessary maintenance therapy.","basis":"workbook_exemplar"},{"id":"M4-I2","question":"Does the clinician select or switch pharmacotherapy to avoid a drug-disease, drug-drug, organ-function, or allergy contraindication?","include_when":"Standard therapy conflicts with a documented allergy, comorbidity, concurrent medication, or renal/hepatic impairment.","exclude_when":"First-line standard therapy has no contraindications or interactions in the patient.","adequate":"Clinician recognizes the constraint, avoids or stops the contraindicated agent, and selects a safe alternative therapeutic class.","insufficient":"Clinician prescribes or continues a contraindicated agent or stops needed treatment without offering a safe alternative.","basis":"unresolved_source_support"},{"id":"M4-I3","question":"Does the clinician discontinue or substitute an over-the-counter or prescribed agent that is actively causing or exacerbating the clinical problem?","include_when":"An active prescribed, over-the-counter, or borrowed medication is driving pathology, symptom flares, or vital sign instability.","exclude_when":"No current medication is exacerbating the presenting condition.","adequate":"Clinician explains the iatrogenic link, advises stopping and avoiding the offending agent, and provides a safer option for symptom relief if needed.","insufficient":"Clinician treats the resulting symptoms while allowing the offending agent to continue.","basis":"unresolved_source_support"},{"id":"M4-I4","question":"Does the clinician address reproductive potential, preconception washout/contraception, or pregnancy safety when prescribing or reviewing therapy?","include_when":"A patient of childbearing potential is prescribed or taking a teratogenic medication, planning conception on high-risk therapy, or currently pregnant.","exclude_when":"Reproductive, preconception, or antenatal medication safety considerations do not apply.","adequate":"Clinician counsels on fetal/teratogenic risks, coordinates effective contraception or safe preconception medication transition/washout, avoids teratogens in pregnancy, and recommends indicated prenatal prophylaxis.","insufficient":"Clinician initiates or continues teratogenic therapy without contraception/washout counseling or leaves unsafe medications unaddressed in pregnancy.","basis":"unresolved_source_support"},{"id":"M4-I5","question":"Does the clinician make an appropriate antimicrobial prescribing or withholding decision and align antimicrobial selection with clinical or microbiologic indications?","include_when":"The current encounter involves a suspected viral or bacterial infection requiring an antimicrobial prescribing, withholding, or culture-directed adjustment decision.","exclude_when":"No infectious presentation or antimicrobial therapy decision applies in the current encounter (symptomatic OTC medication safety boundaries are screened separately under M4-I7).","adequate":"Clinician withholds unneeded antibiotics in self-limiting viral illness with an actionable contingency plan, or selects/adjusts antimicrobial therapy to match clinical and culture susceptibility indications.","insufficient":"Clinician prescribes unwarranted immediate antibiotics for a likely viral illness or continues/initiates an antimicrobial agent discordant with known susceptibilities or clinical indication.","basis":"unresolved_source_support"},{"id":"M4-I6","question":"Does the clinician execute appropriate physiological sequencing, dose titration, step-down/deprescribing, or adverse drug reaction adjustment?","include_when":"Therapy requires staged initiation after confirmation, physiological sequencing, escalation for suboptimal control, deprescribing after remission, or modification for a treatment-emergent adverse effect.","exclude_when":"Unchanged maintenance therapy is effective and well tolerated.","adequate":"Clinician sequences interventions safely, titrates or adds therapy when control is inadequate, steps down therapy upon sustained remission with relapse contingencies, or stops/adjusts regimens causing adverse effects.","insufficient":"Clinician reverses safe physiological sequencing, leaves suboptimal control unaddressed, continues short-term therapy indefinitely without review, or ignores treatment-emergent adverse reactions.","basis":"unresolved_source_support"},{"id":"M4-I7","question":"Does the clinician counsel on safe usage boundaries, dosing limits, or overuse risks for symptomatic over-the-counter medications?","include_when":"The current encounter involves use, patient request, or clinician recommendation of symptomatic over-the-counter analgesics, antipyretics, or decongestants carrying toxicity, rebound, or medication-overuse risks.","exclude_when":"No symptomatic over-the-counter medication safety or overuse boundary applies in the current encounter (antimicrobial decisions are screened under M4-I5).","adequate":"Clinician advises safe dosing frequency, maximum duration limits, and explicit precautions to prevent medication-overuse headache, rebound congestion, or organ toxicity from symptomatic OTC agents.","insufficient":"Clinician recommends or endorses symptomatic OTC medications carrying rebound or overuse risks without specifying safe duration or dosing boundaries.","basis":"unresolved_source_support"}]},{"id":"MOD-05","name":"Shared Decision-Making & Communication Completeness","scope":"Responding to patient concerns, questions, and delivery preferences; weighing individualized risk-benefit trade-offs and assessing decision-making capacity; counseling on conservative-to-surgical hierarchies; addressing unproven remedies and funding boundaries; negotiating care refusal with actionable deferral; and delivering complete communication across turns.","items":[{"id":"M5-I1","question":"Does the clinician explore and respond to the patient's specific concerns, scripted questions, treatment reluctance, or delivery-route preferences?","include_when":"The patient or caregiver raises questions or concerns, expresses hesitation about starting therapy, or prefers a specific administration route or device.","exclude_when":"No specific patient question, concern, reluctance, or route preference is present.","adequate":"Clinician directly answers the patient's questions, validates concerns about side effects or long-term use, and accommodates safe route or device preferences (or explains clearly when a preferred option is clinically unsafe).","insufficient":"Clinician ignores scripted patient questions, dismisses reluctance, or overrides safe patient preferences without explanation.","basis":"workbook_exemplar"},{"id":"M5-I2","question":"Does the clinician guide shared decision-making across competing clinical risks and benefits, including assessing decision-making capacity and consent when insight is impaired?","include_when":"Initiating, extending, or stopping high-stakes therapy involves major competing risks (such as thrombosis vs. bleeding, or neuropsychiatric medication risk in frailty/dementia) or impaired patient insight.","exclude_when":"Treatment follows a straightforward standard without major competing risk trade-offs or capacity concerns.","adequate":"Clinician clearly explains the competing clinical risks and benefits, incorporates patient/family values, and assesses decision-making capacity and informed consent when cognitive impairment or anosognosia is present.","insufficient":"Clinician applies a rigid rule without discussing competing risks or initiates high-risk therapy in an impaired patient without addressing capacity and consent.","basis":"unresolved_source_support"},{"id":"M5-I3","question":"Does the clinician counsel on the hierarchy of conservative, device, minimally invasive, and surgical options?","include_when":"The condition has staged non-surgical and procedural/surgical pathways, or requires explaining why definitive procedural intervention is indicated.","exclude_when":"Management is purely medical and no procedural or surgical options are relevant or raised.","adequate":"Clinician outlines the appropriate progression from conservative/behavioral measures to device or surgical interventions, clarifies procedural expectations and risks, and explains when surgery is optional versus definitively indicated.","insufficient":"Clinician escalates directly to invasive procedures when conservative care is first-line, or omits procedural option counseling.","basis":"workbook_exemplar"},{"id":"M5-I4","question":"Does the clinician provide evidence-based counseling when asked about unproven remedies, supplements, or healthcare funding/eligibility boundaries?","include_when":"The patient asks about complementary supplements, non-recommended modalities, or publicly funded procedures for cosmetic/asymptomatic indications.","exclude_when":"The patient does not inquire about unproven remedies or coverage boundaries.","adequate":"Clinician respectfully explains the lack of efficacy evidence or condition-specific drawbacks and clarifies clinical eligibility versus private/cosmetic options where applicable.","insufficient":"Clinician endorses ineffective interventions as evidence-based or dismisses the patient's inquiry without explanation.","basis":"unresolved_source_support"},{"id":"M5-I5","question":"When a patient hesitates or declines a recommended test or treatment, does the clinician negotiate respectfully and establish an actionable deferral or interim bridging plan?","include_when":"A patient delays, hesitates, or declines recommended diagnostic testing, medication, device therapy, or surgery.","exclude_when":"The patient readily accepts the recommended diagnostic and therapeutic plan.","adequate":"Clinician explores the underlying barrier, explains the clinical rationale without coercion, and arranges an actionable interim safety, bridging, or reassessment plan (scored solely on clinician counseling, never on patient consent).","insufficient":"Clinician pressures the patient, fails to explain the rationale for recommended care, or abandons interim safety planning when the patient declines.","basis":"design_extension"},{"id":"M5-I6","question":"Does the clinician deliver complete, coherent explanations across dialogue turns rather than making unfulfilled promises to explain later?","include_when":"The encounter requires multi-step diagnostic, therapeutic, or prognostic counseling across interactive turns.","exclude_when":"No substantive clinical explanation or counseling is required at the visit.","adequate":"Clinician completes required explanations clearly and coherently across the conversation, ensuring that any topic introduced or promised is substantively delivered before the encounter ends.","insufficient":"Clinician substitutes vague promises (e.g., 'I will explain that later' or 'read the leaflet') for required verbal counseling, or leaves key explanations truncated across turns.","basis":"design_extension"}]},{"id":"MOD-06","name":"Treatment Instruction & Comprehension Verification","scope":"Actual patient teaching on medical device technique, medication administration mechanics, therapeutic onset/adherence/maintenance-vs-rescue roles, structured self-monitoring logs, pre-escalation adherence/technique verification, and meaningful comprehension checks.","items":[{"id":"M6-I1","question":"Does the clinician actually teach or troubleshoot medical device technique rather than merely prescribing or promising instruction?","include_when":"The management plan initiates, continues, or adjusts an inhaler, spacer, peak flow meter, positive airway pressure device, pessary, or compression garment.","exclude_when":"No medical device or specialized delivery apparatus is involved.","adequate":"Clinician actively explains step-by-step device use, reviews technique, or troubleshoots fit/tolerance issues during the visit.","insufficient":"Clinician prescribes or escalates a device without explaining how to use it, or merely promises that someone else will demonstrate it later.","basis":"unresolved_source_support"},{"id":"M6-I2","question":"Does the clinician instruct the patient on required medication timing, meal/protein coordination, posture, or supplement separation?","include_when":"Prescribed therapy requires specific administration mechanics to ensure absorption, prevent mucosal injury, or avoid diurnal side effects.","exclude_when":"Prescribed medications have no special timing, food, postural, or separation requirements.","adequate":"Clinician gives explicit, plain-language instructions on when and how to take the medication relative to meals, sleep, posture, or other supplements.","insufficient":"Clinician prescribes a timing- or posture-sensitive medication without administration instructions.","basis":"unresolved_source_support"},{"id":"M6-I3","question":"Does the clinician explain medication mechanism, expected time to onset, full-course or long-term adherence, and maintenance-versus-rescue roles?","include_when":"The patient starts antimicrobials, preventive/prophylactic agents with delayed onset, chronic disease controllers, or dual maintenance and reliever therapy.","exclude_when":"No pharmacotherapy requiring onset, course-completion, or controller-versus-reliever education is active.","adequate":"Clinician explains what the medication does, when to expect clinical benefit, why completing a course or continuing chronic therapy matters after symptoms improve, and how to distinguish daily maintenance from rescue use.","insufficient":"Clinician issues a prescription without explaining delayed onset, course completion, or controller versus reliever roles.","basis":"unresolved_source_support"},{"id":"M6-I4","question":"Does the clinician instruct the patient on maintaining a structured self-monitoring log and explain actionable target ranges?","include_when":"Longitudinal diagnosis or titration depends on home physiological measurements or structured symptom/trigger diaries.","exclude_when":"Structured home physiological or symptom logging is not clinically relevant.","adequate":"Clinician specifies what parameters to record, measurement frequency, and what target ranges or patterns should prompt review.","insufficient":"Clinician advises vague self-observation without defining structured logging parameters or target expectations.","basis":"workbook_exemplar"},{"id":"M6-I5","question":"Before escalating dose or switching therapy for suboptimal control, does the clinician verify medication adherence, dietary implementation, and device technique?","include_when":"A follow-up visit shows incomplete symptom or biomarker control on an initial therapeutic regimen.","exclude_when":"Initial therapy is effective, or the encounter is an initial baseline assessment.","adequate":"Clinician explicitly checks how consistently the patient is taking the medication, following dietary measures, and using any delivery device before up-titrating or switching classes.","insufficient":"Clinician escalates doses or adds second-line agents without checking adherence or administration technique.","basis":"design_extension"},{"id":"M6-I6","question":"After delivering complex teaching or action plans, does the clinician perform a meaningful understanding check and address low, non-committal, or absent patient responses?","include_when":"The clinician delivers device instruction, multi-step medication/prep rules, or complex safety-netting during the encounter.","exclude_when":"No complex instruction was required, OR the prerequisite teaching/explanation was omitted by the clinician (to prevent duplicate dependent penalties).","adequate":"Clinician invites the patient or caregiver to summarize or demonstrate how they will carry out the plan, and if the response is minimal, confused, or absent, clarifies and re-engages supportively (scored strictly on clinician behavior).","insufficient":"Clinician finishes complex instruction without checking comprehension, or ignores cues of confusion or minimal/non-committal responses.","basis":"design_extension"}]},{"id":"MOD-07","name":"Functional Adaptation, Public/Legal Safety & Prevention","scope":"Condition-specific non-pharmacological self-care and nutrition/bone health adapted to daily life; occupational hazard mitigation and graded return to work; driving, household, wandering, and advance care safety planning; substance cessation support; infection transmission precautions; and preventive immunizations and psychosocial/caregiver coaching.","items":[{"id":"M7-I1","question":"Does the clinician provide condition-specific non-pharmacological self-care, dietary, bone-health, or activity strategies tailored to the patient's daily constraints?","include_when":"Targeted dietary, postural, fluid, bone-health, physical activity, or symptom-management measures directly modify disease activity or symptom burden.","exclude_when":"Non-pharmacological lifestyle measures have no specific therapeutic role in the visit.","adequate":"Clinician recommends actionable, condition-specific dietary, bone-protective, physical, or self-care adaptations tailored to the patient's routine and disclosed barriers.","insufficient":"Clinician offers only generic wellness platitudes or ignores practical barriers in the patient's daily schedule.","basis":"workbook_exemplar"},{"id":"M7-I2","question":"Does the clinician advise on occupational hazard mitigation, workplace ergonomic adjustments, or graded return-to-work and activity restrictions?","include_when":"Workplace exposures or physical demands aggravate the condition, or recovery/cardiopulmonary risk requires temporary activity restriction or graded reintegration.","exclude_when":"Occupation and physical activities are unaffected by the condition or treatment.","adequate":"Clinician provides concrete workplace exposure/ergonomic modifications, activity restrictions pending clearance, or a graded return-to-work plan.","insufficient":"Clinician overlooks occupational triggers or fails to guide safe activity restriction and work reintegration.","basis":"unresolved_source_support"},{"id":"M7-I3","question":"Does the clinician counsel on driving/machinery safety, household/fall/wandering/seizure precautions, or advance care planning when capacity or consciousness is affected?","include_when":"The presentation involves syncope, seizures, daytime somnolence, visual/motor impairment, or progressive cognitive decline affecting driving, home safety, or future decision-making capacity.","exclude_when":"Consciousness, motor/visual control, and cognitive capacity for driving and independent safety are intact.","adequate":"Clinician advises appropriate driving precautions and regulatory notification per case context, addresses household/seizure/wandering safety, and discusses future care/legal planning in progressive cognitive decline.","insufficient":"Clinician omits driving or home-safety precautions in high-risk neurological/cardiopulmonary states or neglects future planning in progressive dementia.","basis":"unresolved_source_support"},{"id":"M7-I4","question":"Does the clinician link active tobacco, alcohol, or substance use to the patient's condition and offer cessation or harm-reduction support?","include_when":"Active smoking, excess alcohol, or substance use drives disease progression, surgical/bleeding risk, medication toxicity, or transplant eligibility.","exclude_when":"The patient does not use tobacco, excess alcohol, or harmful substances.","adequate":"Clinician explains how the substance directly affects the patient's condition or treatment safety and offers nonjudgmental behavioral or pharmacological cessation support.","insufficient":"Clinician notes substance use in history but fails to explain its clinical impact or offer cessation support.","basis":"workbook_exemplar"},{"id":"M7-I5","question":"Does the clinician counsel on infection transmission precautions, hygiene measures, or contact tracing when a transmissible condition is present?","include_when":"The patient has a communicable respiratory, enteric, bloodborne, or sexually transmitted infection, or recurrent infection linked to hygiene practices.","exclude_when":"No communicable infection or hygiene-preventable recurrence risk is present in the current encounter.","adequate":"Clinician instructs the patient on isolation, masking, barrier protection, hygiene, or household/partner contact tracing matched to the transmission route.","insufficient":"Clinician treats the infection pharmacotherapeutically but omits indicated transmission precautions, hygiene measures, or contact tracing counseling.","basis":"unresolved_source_support"},{"id":"M7-I6","question":"Does the clinician recommend indicated preventive immunizations matched to the patient's condition, age, or exposure risk?","include_when":"Chronic disease, age, clinical status, or exposure risk in the current encounter warrants preventive vaccination counseling.","exclude_when":"No preventive immunization indication is present in the current encounter (in-encounter psychosocial or caregiver support is screened separately under M7-I7).","adequate":"Clinician recommends relevant preventive vaccinations and explains their role in preventing avoidable complications for the patient's risk profile.","insufficient":"Clinician omits indicated preventive immunization advice when current-encounter facts establish a clear vaccination need.","basis":"unresolved_source_support"},{"id":"M7-I7","question":"Does the clinician provide empathetic psychosocial validation and practical in-encounter behavioral or caregiver coping support?","include_when":"The patient or caregiver experiences illness-related emotional distress, bereavement, behavioral challenges, or caregiving strain during the current encounter.","exclude_when":"No psychosocial distress or caregiver strain is present in the current encounter (preventive immunization is screened under M7-I6 and formal service referrals belong to MOD-08 M8-I3).","adequate":"Clinician acknowledges emotional or caregiver burden empathetically and offers practical in-encounter behavioral coping or redirection strategies (while formal service referrals belong to MOD-08).","insufficient":"Clinician ignores overt patient distress or caregiver exhaustion, or offers dismissive reassurance without practical in-encounter supportive guidance.","basis":"unresolved_source_support"}]},{"id":"MOD-08","name":"Care Coordination, Surveillance & Follow-Up Closure","scope":"Immediate emergency/inpatient transfer triage; medical, surgical, obstetric, and urgent cancer specialist referrals; allied health, rehabilitation, dietetics, optometry, and social support referrals; longitudinal lab/imaging surveillance schedules; condition-specific red-flag safety-netting; and routine follow-up scheduling with pending-result loop closure.","items":[{"id":"M8-I1","question":"Does the clinician arrange immediate emergency department transfer or hospital admission when the presentation is acutely unstable?","include_when":"The patient exhibits life- or organ-threatening instability requiring immediate inpatient resuscitation, monitoring, or emergency intervention.","exclude_when":"The patient is clinically stable for outpatient evaluation and management.","adequate":"Clinician recognizes the acute instability, explains why outpatient care is unsafe, and arranges immediate emergency transfer or hospital admission.","insufficient":"Clinician manages an unstable emergency with routine outpatient testing or delayed clinic follow-up.","basis":"unresolved_source_support"},{"id":"M8-I2","question":"Does the clinician initiate indicated medical, surgical, obstetric, or urgent suspected-cancer specialist referrals and coordinate cross-specialty priorities?","include_when":"Definitive diagnosis, procedural intervention, high-risk pregnancy/comorbidity co-management, or suspected malignancy requires specialist referral.","exclude_when":"The condition is appropriately managed within primary care without specialist referral.","adequate":"Clinician initiates the appropriate specialist or multidisciplinary referral at the warranted urgency tier and coordinates perioperative or cross-specialty priorities.","insufficient":"Clinician omits a needed specialist referral, refers prematurely when primary care management is indicated, or fails to coordinate conflicting specialty needs.","basis":"unresolved_source_support"},{"id":"M8-I3","question":"Does the clinician coordinate indicated allied health, structured rehabilitation, dietetics, optometry/ophthalmology, or social support referrals?","include_when":"Multidisciplinary non-physician services (such as cardiopulmonary rehab, physiotherapy, occupational therapy home assessment, dietitian, retinal/eye screening, psychotherapy, or social/respite services) are clinically supported.","exclude_when":"No allied health, rehabilitation, eye-care, or social support referrals are indicated.","adequate":"Clinician recommends and coordinates the specific multidisciplinary referrals matched to the patient's functional, nutritional, visual, or psychosocial needs.","insufficient":"Clinician relies solely on brief verbal advice when structured rehabilitation, dietetics, eye screening, or social care referral is warranted.","basis":"workbook_exemplar"},{"id":"M8-I4","question":"Does the clinician establish a scheduled longitudinal laboratory, biomarker, imaging, or endoscopic surveillance plan?","include_when":"Ongoing management requires periodic objective monitoring for treatment efficacy, drug toxicity, post-procedural recurrence, or silent disease progression.","exclude_when":"The condition is acute and self-limiting with no requirement for longitudinal biochemical or imaging surveillance.","adequate":"Clinician outlines a condition-appropriate schedule for repeat laboratory, drug-safety, imaging, or endoscopic monitoring and explains its purpose.","insufficient":"Clinician starts chronic/high-risk therapy or diagnoses a condition requiring surveillance without arranging longitudinal monitoring.","basis":"unresolved_source_support"},{"id":"M8-I5","question":"Does the clinician provide condition-specific red-flag warning signs, non-improvement thresholds, and emergency escalation instructions?","include_when":"The working diagnosis or outpatient treatment carries a specific risk of acute deterioration, complication, or treatment failure.","exclude_when":"The patient is being transferred immediately to emergency/inpatient care at the current visit, or no plausible acute deterioration pathway applies.","adequate":"Clinician names specific warning symptoms or non-improvement signs relevant to the condition/treatment and states clearly when to seek urgent clinic review versus immediate emergency care.","insufficient":"Clinician gives only generic 'return if worse' advice without specifying warning signs or escalation urgency.","basis":"unresolved_source_support"},{"id":"M8-I6","question":"Does the clinician schedule an appropriate routine follow-up interval and modality and close the loop on any pending investigation results?","include_when":"The visit requires a scheduled review appointment, transition to as-needed follow-up upon remission, or a plan to review newly ordered or still-pending test results.","exclude_when":"The patient is transferred immediately to inpatient care and no outpatient follow-up or pending-result plan is applicable at this stage.","adequate":"Clinician specifies the timeframe and modality (in-person vs. virtual) for the next review (or PRN discharge upon resolution), states what will be reassessed, and explains how and when pending test results will be communicated.","insufficient":"Clinician orders tests or adjusts therapy without arranging follow-up or explaining how pending results will be reviewed.","basis":"workbook_exemplar"}]}],"common_rules":["UNIVERSAL SCREENING WITH DISTINCT CHECKLISTS: All eight specialists read the same authorized current-encounter packet. Each specialist evaluates ONLY its own assigned six or seven questions; together they cover 50 questions, not eight copies of the entire checklist. Encounter labels and modifiers guide attention but never exclude a specialist. Every assigned item and independently applicable facet receives applicable, not_applicable, or unresolved with a case-specific reason. One covered facet does not establish coverage of another, and screening questions do not automatically become separate scored criteria.","CURRENT-ENCOUNTER SCOPING & ANTI-HINDSIGHT BOUNDARIES: Future rubric generation inputs are scoped strictly to the CURRENT encounter (Visit N). When a case has multiple visits, build separate visit-specific author packets containing only eligible prior/current clinician-visible facts ('direct_source_ids'), currently elicitable patient-script disclosures at Visit N ('dialogue_source_ids'), and allowed scenario context ('context_source_ids'), with no later-visit revelations, hypothetical future states, or answer keys. All 8 modules screen each scoped visit packet independently without requiring or permitting author access to future visits (though the descriptive source-study map may still display all 3 visits). Proactive clinician inquiry into plausible risks using allowed scenario context is permitted, but criteria must never require the patient to supply an unscripted answer or penalize a clinician before the clinical opportunity to elicit or observe information exists.","STRICT SEPARATION OF AUTHOR INPUTS FROM REVIEWER-ONLY ANSWER-DERIVED NOTES: Future rubric authors receive only current authorized case facts, visit-scoped patient-script context with access labels, generic checklist questions/completion boundaries, and explicit supplied clinician minima. All legacy rubrics, examiner mark schemes, expected-management/justification/diagnosis columns, same-case checklist exemplars, and all archived case-analysis notes (W1-R002..W1-R099 and W2-R002..W2-R025) or UCQs derived in whole or in part from examiner answer columns remain strictly REVIEWER-ONLY. Case-fact ambiguities may be exposed to authors only if their entire provenance is strictly case-fact-only; never merely scrub words from answer-derived notes or feed a prior answer back through notes.","CLINICIAN-ONLY SCORING TARGET: Score only observable clinician behaviors (inquiring, examining, ordering, explaining, prescribing, counseling, checking understanding, coordinating, safety-netting). Never score standardized patient or caregiver behavior, disclosure completeness, emotional reaction, demonstration accuracy, recall, or treatment compliance, and never turn compound checklist facets into patient performance targets.","PRESERVATION OF SUPPLIED CLINICIAN MINIMA WITHOUT INVENTED FLOORS: Declared minima are explicitly supplied clinician requirements for a case/visit, not generic schema minima. Preserve supplied clinician minima unchanged and do not invent a generic mandatory minimum floor set; every checklist item is evaluated strictly against current-encounter support.","SINGLE PRIMARY OWNER & NARROW ITEM BOUNDARIES WITHOUT FORCED SPLITTING: Each independent clinical behavior has one primary owning module (MOD-01..MOD-08) per the ownership rules. Keep distinct therapeutic and preventive domains separated—specifically M4-I5 (antimicrobial decision/stewardship) vs. M4-I7 (symptomatic OTC safety boundaries), and M7-I6 (preventive immunization) vs. M7-I7 (in-encounter psychosocial/caregiver support). Do not bundle duties separated across visits or distinct failure modes, and do not force separate scored criteria when multiple applicable communication facets naturally co-occur in a single turn.","NO DUPLICATE DEPENDENT PENALTIES: When a secondary behavior depends on a prerequisite clinician action (e.g., M6-I6 checking patient understanding after delivering device or medication teaching in M6-I1..I3), if the prerequisite explanation or teaching never occurred, penalize only the omitted prerequisite teaching and do not impose a second penalty for omitting the dependent understanding check. Independent clinical opportunities remain separately gradable.","ACTUAL DELIVERY & COMPLETE MULTI-TURN COMMUNICATION: Score actual clinician teaching, explanation, and counseling delivered coherently across dialogue turns. Merely promising to explain later, offering a leaflet in place of required verbal counseling, or leaving explanations fragmented/incomplete across turns is insufficient.","NO UNVERIFIED SPECIFICS OR ASSUMED-SAFE CLASS GENERALIZATION: Do not encode workbook-specific drugs, doses, time intervals, numerical cutoffs, or jurisdiction-specific legal rules as mandatory requirements. Where a source workbook recommendation is clinically disputed, internally contradictory, or unverified (including section-heading-only citations such as M7-I5), do NOT assume that generalizing to a 'safe class-level' intervention resolves the uncertainty: keep the disputed recommendation 'unresolved' (not emitted as a scored clinical mandate), while a separate case-fact-supported process criterion to assess, clarify, or discuss options may be drafted if independently valid. Remaining workbook source quotes in the design are unvalidated examples only.","POST-GENERATION REVIEWER AMBIGUITY PRESERVATION: Preserve archived case analyses, examiner-column contradictions, and UCQs intact in reviewer-only records. Apply them post-generation as review findings; do not feed answer-derived content back to authors. HOST SCHEMA GUARD (integration correction, not Argon-authored): criteria[].review_status remains 'draft_unreviewed', with severity.grade and severity.critical null and clinical_validation false. 'Unresolved' is an external checklist/review-sidecar disposition, never a new review_status value. Preserve original author output unchanged. Reviewer-only answer-derived observations stay in a separate linked review record; only source-bound notes that satisfy the existing contract may appear in a separately labeled derivative model_notes[] artifact. Notes with reviewer-only source IDs absent from the authorized case stay in the review sidecar. No clinical approval or finalization follows."],"ownership_rules":[{"event":"Ordering an investigation vs. explaining its purpose vs. interpreting returned results vs. closing the loop on pending results","primary_module":"MOD-02 (M2-I3/I6 for ordering) / MOD-03 (M3-I1 for test purpose; M3-I2 for returned result interpretation) / MOD-08 (M8-I6 for scheduling result review)","other_module":"MOD-02, MOD-03, MOD-08","distinction":"MOD-02 owns selecting and ordering the test; MOD-03 M3-I1 owns proactively explaining why the test is ordered; MOD-03 M3-I2 owns interpreting returned results at a subsequent visit; MOD-08 M8-I6 owns scheduling the follow-up to review pending results."},{"event":"Eliciting undisclosed medications or allergies vs. stopping/switching an interacting or contraindicated drug","primary_module":"MOD-01 (M1-I3 for history elicitation) / MOD-04 (M4-I2/I3 for regimen change)","other_module":"MOD-01, MOD-04","distinction":"Asking about concurrent medications/allergies is an independent history duty (MOD-01); discontinuing an offending agent or switching to a safe alternative class once known is a therapeutic safety duty (MOD-04)."},{"event":"Probing discordant test results or hidden non-adherence vs. verifying adherence/technique prior to dose escalation","primary_module":"MOD-01 (M1-I4 for diagnostic/biomarker discordance) / MOD-06 (M6-I5 for pre-escalation check)","other_module":"MOD-01, MOD-06","distinction":"MOD-01 M1-I4 owns investigating contradictions between objective labs/spirometry and reported history; MOD-06 M6-I5 owns verifying medication adherence and device technique before stepping up pharmacotherapy. If both refer to the exact same verbal check at a single visit, MOD-06 M6-I5 emits for therapeutic escalation and MOD-01 logs merged_via_shared_ownership."},{"event":"Switching therapy for an absolute contraindication vs. aligning delivery route/regimen with patient preference","primary_module":"MOD-04 (M4-I2 for medical contraindication) / MOD-05 (M5-I1 for preference alignment)","other_module":"MOD-04, MOD-05","distinction":"MOD-04 owns avoiding medically unsafe drugs; MOD-05 owns accommodating patient route/device preferences among clinically safe options."},{"event":"Delivering device or medication instruction vs. checking patient comprehension","primary_module":"MOD-06 (M6-I1/I2/I3 for instruction; M6-I6 for comprehension check)","other_module":"MOD-06 internal","distinction":"Teaching mechanics/adherence and checking comprehension are distinct items, but M6-I6 is strictly dependent on teaching having occurred: if the clinician omitted the required teaching, penalize only the teaching item (M6-I1/I2/I3) and never double-penalize M6-I6 for the same omission."},{"event":"Counseling on hereditary risk vs. ordering a genetic test vs. referring to a genetic counselor/specialist","primary_module":"MOD-03 (M3-I6 for hereditary counseling) / MOD-02 (M2-I3 for test order) / MOD-08 (M8-I2 for referral)","other_module":"MOD-02, MOD-03, MOD-08","distinction":"MOD-03 M3-I6 covers explaining inheritance patterns and family implications; MOD-02 covers ordering genetic lab tests; MOD-08 covers referring to genetic counseling or specialty clinics."},{"event":"Counseling on procedural/surgical option hierarchies vs. executing the surgical or specialist referral","primary_module":"MOD-05 (M5-I3 for option counseling) / MOD-08 (M8-I2 for referral execution)","other_module":"MOD-05, MOD-08","distinction":"MOD-05 M5-I3 owns shared decision-making across conservative and interventional options; MOD-08 M8-I2 owns placing and coordinating the specialist referral."},{"event":"Eliciting functional/occupational impact and access barriers vs. advising workplace or lifestyle adaptations","primary_module":"MOD-01 (M1-I6 for inquiry) / MOD-07 (M7-I1/I2 for adaptation advice)","other_module":"MOD-01, MOD-07","distinction":"MOD-01 M1-I6 owns proactively asking about functional impact, access, self-management capability, and social support; MOD-07 M7-I1/I2 owns counseling on tailored lifestyle or workplace adjustments."},{"event":"Pre-treatment baseline safety labs vs. longitudinal post-treatment toxicity/efficacy surveillance","primary_module":"MOD-02 (M2-I6 for baseline clearance) / MOD-08 (M8-I4 for longitudinal surveillance)","other_module":"MOD-02, MOD-08","distinction":"MOD-02 M2-I6 owns baseline organ-function or safety screening prior to starting therapy; MOD-08 M8-I4 owns scheduled repeat monitoring after therapy is underway."},{"event":"Routine scheduled follow-up and pending-result loop closure vs. urgent red-flag safety-netting","primary_module":"MOD-08 (M8-I6 for routine follow-up/result closure; M8-I5 for emergency safety-netting)","other_module":"MOD-08 internal","distinction":"M8-I6 owns setting the routine review timeframe/modality and pending-result plan; M8-I5 owns specifying acute red-flag warning signs and emergency return instructions. They must never be bundled into a single criterion."},{"event":"Withholding unindicated diagnostic tests vs. antimicrobial prescribing/withholding stewardship vs. symptomatic OTC medication safety boundaries","primary_module":"MOD-02 (M2-I5 for diagnostic tests) / MOD-04 (M4-I5 for antimicrobials; M4-I7 for symptomatic OTC safety boundaries)","other_module":"MOD-02, MOD-04","distinction":"MOD-02 M2-I5 owns diagnostic investigation stewardship; MOD-04 M4-I5 owns antibiotic withholding and susceptibility-guided antimicrobial selection; MOD-04 M4-I7 owns safe duration, dosing limits, and rebound/overuse warnings for symptomatic OTC medications."},{"event":"Preventive immunization counseling vs. in-encounter empathetic caregiver/psychosocial coaching vs. formal referrals to psychology, social work, or respite care","primary_module":"MOD-07 (M7-I6 for preventive immunization; M7-I7 for in-visit psychosocial/caregiver support) / MOD-08 (M8-I3 for formal referral)","other_module":"MOD-07, MOD-08","distinction":"MOD-07 M7-I6 covers recommending indicated preventive vaccinations; MOD-07 M7-I7 covers in-encounter emotional validation and behavioral redirection coaching; MOD-08 M8-I3 covers coordinating formal referrals to psychotherapy, occupational therapy, social work, or respite services."}]};
