mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:'base',themeVariables:{fontFamily:'Avenir Next, Segoe UI, sans-serif',fontSize:'18px',primaryColor:'#c6e1e9',primaryTextColor:'#192c33',primaryBorderColor:'#597887',lineColor:'#45606a',clusterBkg:'#f8faf9',clusterBorder:'#c5cecd',edgeLabelBackground:'#fffef9'},flowchart:{htmlLabels:true,wrappingWidth:420,minNodeWidth:220,curve:'basis',nodeSpacing:64,rankSpacing:70,padding:16,useMaxWidth:false}});
function viewIds(){return current.groups.flatMap(g=>g[2]);}
function labelLines(text,limit=44){return DiagramLayout.wrapLabel(text,limit);}
function source(v){
  let s='flowchart TB\n';
  for(const id of v.groups.flatMap(g=>g[2]))s+=`${id}[${JSON.stringify(labelLines(nodes[id].title))}]\n`;
  for(const[a,b,label,style]of v.edges){const text=JSON.stringify(labelLines(label,24));s+=style==='dashed'?`${a} -. ${text} .-> ${b}\n`:`${a} -->|${text}| ${b}\n`;}
  s+='classDef model fill:#c6e1e9,stroke:#426b76,color:#17343d;\nclassDef code fill:#dadddf,stroke:#65757c,color:#23363c;\nclassDef human fill:#f0d196,stroke:#967137,color:#35260f;\nclassDef artifact fill:#cbe1c8,stroke:#527450,color:#173325;\n';
  for(const id of v.groups.flatMap(g=>g[2]))s+=`class ${id} ${nodes[id].kind};\n`;return s;
}
function hideTooltip(){$('tooltip').hidden=true;}
function tooltip(el,id){const t=$('tooltip'),r=el.getBoundingClientRect();t.textContent=id==='specialists'&&current.id==='rubrics'?(teamExpanded?'Collapse eight specialists':'Expand eight specialists'):nodes[id].subtitle+' · Open stage explanation';t.hidden=false;t.style.left=Math.max(8,Math.min(innerWidth-t.offsetWidth-8,r.left))+'px';t.style.top=(r.top>70?r.top-t.offsetHeight-8:Math.min(innerHeight-t.offsetHeight-8,r.bottom+8))+'px';}
