async function toggleTeam(){teamExpanded=!teamExpanded;await render(views.find(v=>v.id==='rubrics'));$('team-toggle').focus();if(teamExpanded&&innerWidth<800)showSpecialistPicker();}
function showTopics(node){
 const section=$('dialog-topics-section'),list=$('dialog-topics');list.replaceChildren();section.hidden=!node.topics;
 for(const topic of node.topics||[]){
  const li=document.createElement('li'),title=document.createElement('strong');title.textContent=topic.id+' · '+topic.question;li.append(title);
  const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='When it applies and what it looks for';details.append(summary);
  for(const[key,label]of [['include_when','Consider when'],['exclude_when','Usually not applicable when'],['adequate','Catalog example of adequate behavior'],['insufficient','Catalog example of insufficient behavior'],['basis','Recorded source-support status']]){
   if(!topic[key])continue;const para=document.createElement('p'),b=document.createElement('strong');b.textContent=label+': ';const readable=key==='basis'?({unresolved_source_support:'Source support not yet settled',workbook_exemplar:'Drawn from a workbook example',design_extension:'Added as a design extension'}[topic[key]]||topic[key])+' — catalog-item provenance, not case applicability or clinical approval':topic[key];para.append(b,document.createTextNode(readable));if(key==='basis')para.title='Source code: '+topic[key];details.append(para);
  }li.append(details);list.append(li);
 }
}
function showConnections(id){const list=$('dialog-links');list.replaceChildren();for(const[a,b,label,style]of current.edges){if(a!==id&&b!==id)continue;const li=document.createElement('li');li.textContent=(b===id?'Receives from '+nodes[a].title:'Sends to '+nodes[b].title)+' — '+label+(style==='dashed'?' (supporting / side path; see label)':'');list.append(li);}$('dialog-links-section').hidden=!list.children.length;}
