function centerTeam(){} // The fitted expanded graph keeps the full team in view.
function scrollHint(){const p=$('diagram-viewport'),h=$('scroll-hint');if(!h)return;h.hidden=listMode;const more=p.scrollWidth>p.clientWidth+3||p.scrollHeight>p.clientHeight+3;h.textContent=more?'Zoomed view · scroll to explore':'Fitted to canvas';}
function applyZoom(){
 const svg=$('diagram').querySelector('svg');if(!svg||listMode)return;const vb=svg.viewBox.baseVal,panel=$('diagram-viewport');
 const fit=DiagramLayout.fitScale({width:vb.width,height:vb.height},{width:panel.clientWidth,height:panel.clientHeight});
 const actual=fit*scale;svg.style.width=(vb.width*actual)+'px';svg.style.height=(vb.height*actual)+'px';
 $('diagram').style.width=(vb.width*actual)+'px';$('diagram').style.height=(vb.height*actual)+'px';
 $('fit').title='Fit entire diagram · '+Math.round(actual*100)+'% of original size';requestAnimationFrame(scrollHint);
}
