function updateList(){$('stage-list').hidden=!listMode;$('diagram-viewport').hidden=listMode;$('list-toggle').setAttribute('aria-pressed',String(listMode));$('list-toggle').textContent=listMode?'Show diagram':'Stage list';hideTooltip();scrollHint();if(!listMode)requestAnimationFrame(()=>{applyZoom();$('diagram-viewport').scrollTo(0,0);});}
function navigateView(v){teamExpanded=false;return render(v);}
async function render(v){v=SpecialistModel.expand(v.id==='rubrics'?views.find(x=>x.id==='rubrics'):v,specialistCatalog,teamExpanded);current=v;$('team-toggle').hidden=v.id!=='rubrics';$('team-about').hidden=v.id!=='rubrics';$('specialist-list').hidden=v.id!=='rubrics';$('team-toggle').textContent=teamExpanded?'Collapse eight specialists':'Expand eight specialists';$('team-toggle').setAttribute('aria-expanded',String(teamExpanded));const seq=++renderNumber;scale=1;hideTooltip();for(const b of $('views').children)b.setAttribute('aria-current',b.dataset.view===v.id?'page':'false');$('compact-title').textContent=String(views.findIndex(x=>x.id===v.id)+1).padStart(2,'0')+' · '+v.short;$('view-kicker').textContent=v.subtitle;$('view-title').textContent=v.title;$('view-description').textContent=v.description;$('boundary-title').textContent=v.boundary;$('boundary-copy').textContent=v.note;$('render-status').textContent='Drawing the pipeline…';$('diagram').replaceChildren();$('stage-list').replaceChildren();$('connection-list').replaceChildren();
for(const id of viewIds()){const b=document.createElement('button');b.className='stage-card';b.type='button';b.dataset.node=id;const strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=nodes[id].title;span.textContent=nodes[id].subtitle;b.append(strong,span);if(id==='specialists'&&v.id==='rubrics'){b.setAttribute('aria-expanded',String(teamExpanded));span.textContent=teamExpanded?'Tap to collapse the eight specialists':'Tap to expand the eight specialists';}b.onclick=()=>activateNode(id,b);$('stage-list').append(b);}
for(const[a,b,label,style]of v.edges){const li=document.createElement('li');li.textContent=nodes[a].title+' → '+nodes[b].title+' · '+label+(style==='dashed'?' (supporting / side path; see label)':'');$('connection-list').append(li);}
updateList();try{const result=await mermaid.render('pipeline-'+seq,source(v));if(seq!==renderNumber)return;$('diagram').innerHTML=result.svg;for(const el of $('diagram').querySelectorAll('g.node')){const id=viewIds().find(id=>(el.id.startsWith('flowchart-'+id+'-')||el.id.includes('-flowchart-'+id+'-')));if(!id)throw Error('Unmapped diagram node '+el.id);el.dataset.node=id;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label',nodes[id].title+': open explanation');el.setAttribute('aria-haspopup','dialog');if(id==='specialists'&&v.id==='rubrics'){el.removeAttribute('aria-haspopup');el.setAttribute('aria-expanded',String(teamExpanded));el.setAttribute('aria-label',nodes[id].title+': '+(teamExpanded?'collapse':'expand')+' eight specialists');}el.addEventListener('click',()=>activateNode(id,el));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activateNode(id,el);}});el.addEventListener('pointerenter',()=>tooltip(el,id));el.addEventListener('pointerleave',hideTooltip);el.addEventListener('focus',()=>tooltip(el,id));el.addEventListener('blur',hideTooltip);}applyZoom();$('diagram-viewport').scrollTo(0,0);centerTeam();$('render-status').textContent=`+ or Stage list to read · ${viewIds().length} stages · ${v.edges.length} connections · View details lists them all.`;}catch(e){$('render-status').textContent='The diagram could not render. All stage explanations remain available in the stage list.';listMode=true;updateList();console.error(e);}}
for(const [i,v]of views.entries()){const b=document.createElement('button');b.type='button';b.dataset.view=v.id;const title=document.createElement('span'),small=document.createElement('small');title.textContent=String(i+1).padStart(2,'0')+'  '+v.short;small.textContent=v.subtitle;small.hidden=true;b.append(title,small);b.onclick=()=>{history.replaceState(null,'','#'+v.id);navigateView(v);};$('views').append(b);}
async function showSpecialistPicker(){if(!teamExpanded){teamExpanded=true;await render(views.find(v=>v.id==='rubrics'));}infoOpener=document.activeElement;$('info-title').textContent='Eight rubric-writing specialists';const target=$('info-content');target.replaceChildren();const note=document.createElement('p');note.textContent='Choose a specialist to read its role and exact screening topics. This list is an accessible alternative to the expanded map.';target.append(note);const list=document.createElement('div');list.className='specialist-picker';for(const row of SpecialistModel.specialists(specialistCatalog)){const button=document.createElement('button');button.type='button';button.dataset.specialist=row.id;button.textContent=row.module+' · '+row.name+' · '+row.topics.length+' topics';button.onclick=()=>showNode(row.id,button);list.append(button);}target.append(list);hideTooltip();if(!$('info-dialog').open)$('info-dialog').showModal();$('close-info').focus();}
let infoOpener=null;
function showInfo(title,sourceId){infoOpener=document.activeElement;$('info-title').textContent=title;const target=$('info-content');target.replaceChildren();const src=$(sourceId);if(sourceId==='view-content'){const copy=src.cloneNode(true);copy.hidden=false;copy.removeAttribute('id');for(const el of copy.querySelectorAll('[id]'))el.removeAttribute('id');target.append(copy);}else target.append(src.content.cloneNode(true));hideTooltip();$('info-dialog').showModal();$('close-info').focus();}
for(const[id,title,sourceId]of [['outputs-button','What comes out','outputs-content'],['help-button','How to read this','help-content'],['status-button','Current status','status-content'],['view-info-button','View details','view-content']])$(id).onclick=()=>showInfo(title,sourceId);
$('close-info').onclick=()=>$('info-dialog').close();$('info-dialog').addEventListener('close',()=>{if(infoOpener&&infoOpener.isConnected)infoOpener.focus();});
